    s=json.dumps(rec)
    if 'Demo pair 1 input' not in s and 'Demo pair 2 input' not in s: continue
    # message content can be nested; extract visible text recursively
    def texts(x):
        if isinstance(x,str): yield x
        elif isinstance(x,dict):
            for v in x.values(): yield from texts(v)
        elif isinstance(x,list):
            for v in x: yield from texts(v)
    for txt in texts(rec):
